    keydownDefinitions.unshift.apply(keydownDefinitions, MORE.map(function (r) { return { open: r[0], close: r[1], className: r[2] }; }));

    function titleize(t) { return t.replace(/^(gel|mkt)-/, '').replace(/-chip$/, '').replace(/-/g, ' ').replace(/\b[a-z]/g, function (c) { return c.toUpperCase(); }); }
    const FAMILIES = [];
